    (1, 5, '" ወደቂቀ ፡ ራጉኤል ፡ ናኬት ፡ ዛሬ ፡ ወሳሜ ፡ ወሞ። 1ዕ ጃወደቁቁቱ ፡ ስይር ፡ ሎጦን ፡ ስበል ፡ ወሴሌቤጎን ፡ ወአናን ፡ ወዴስን ፡ ወአዕር ፡ ወሬሰን።'),
