    (1, 9, 'ያ “ ሇሇ ዞጻ ሪና „ያቑን " 5 ወክሉ ፡ ነገሥቶሙ ፡ ኣለ ፡ ነግሠ ፡ ለኤዶም ፡ አምቅድመ ፡ ይንገሥ ፡ ንጉሥ። ፡ ለደቂቀ ፡ አስራኤል።'),
    (1, 10, 'በለቅ ፡ ወልሩ ፡ ለቤፆር ፡ ወስመ ፡ ሀገሩ ፡ ዴናበ። "ወሞተ ፡ በ ላቅ ፡ ወነግሠ ፡ ህየንጊገ፡ሁ ፡ አ.ዮብብ ፡ ወልዴ።'),
