        12,
        '"ወሞተ ፡ አሶም ፡ ወነግሠ ፡ ህየንቱሆሁ ፡ አዳድ ፡ ወልደ ፡ በራድ ፡ ዘቀተለ ፡ ምድያም ፡ በፈለገ ፡ ሞአብ ፡ ወስመ ፡ ብሔሩ ፡ ጌቴም። "ወሞተ ፡ አዳድ ፡ ወነግሠ ፡ ህየንቴሁ ፡ ስማአ ፡ አምሰቃ።',
