    (1, 13, '"ወሞተ ፡ ስማክ ፡ ወነግሠ ፡ ህየንቴሁ ፡ ሰኡል ፡ አምሮቦት ፡ አንተ ፡ ኀበ ፡ ተከዚ።'),
    (1, 14, "ወሞተ ፡ ሰ ኩል ፡ ወነግሠ ፡ ህየንቱሁ ፡ በለኤኖን ፡ ወልደ ፡ አክበር።"),
    (1, 15, 'ወሞተ ፣ በላኤናን ፡ ወነግ " 0 ሠ ህየንቱቴሁ ፡ አዳድ ፡ ወስመ ፡ ብሒፋ ፡ ፌጎ ር ፡ ወስመ ፡ ብእሲቱ ፡ ማጤቤዓል ፡ ወ ለተ ፡ መጠርት።'),
