    (1, 18, "ሚዘሐብ. ~~ 51. ወመስፍን] ላ ዕክ፤. ወ. —- 0. ጎስምገ 1 ጎስስም. — 532. ኤልሳእ] ኮ ኤልሳ. ~~ 25. መብ ሰር] ኋ መብስር.።"),
    (1, 19, "11, መወከያ ፡።"),
    (1, 20, "ስበ ሂጋ. ፡ በ።"),
    (1, 21, "ዊቁ ፡ ስበራጮል ፡ ር ሠል ፡ በያ / ያ፡፣ ቤቲ. ፡ ሀዳ ፡ ይስከር ፡ ዛቢ.ሎን ፡ ዮሴፍ ፡ ብንያም ፡ ዳን ፡ ንፍታሌም ፡ ጋድ ፡ አሴር።"),
    (1, 22, '"ወደቂቁ ፡ ለ ይሁዳ ፡ ዔር ፣ አውናን ፡ ሴሎሙ ፡ ሠለስቱ ፡ ተወልዳ. ፡ ሎቱ ፡ አምወለተ ፡ ሰቁ ፡ ከነፍ 5 ዊዥ።'),
    (1, 23, "ወከሃ ፡ ዔር ፡ በዙሩ ፡ ለይሁዳ ፡ አኩዩ ፡ በቅድመ ፡ አግዚኣብሔር ፡ ወቀተሉሎ።"),
    (1, 24, '"ወትፅማር ፡ ሐማቱ ፡ ወለደት ፡ ሎቱ ፡ ሬስሃ ፡ ወዛራሃ።'),
    (1, 25, "ወዙሉ ፡ ደቂቁ ፡ ለይሁዳ ፡ =» ምስቱ።"),
    (1, 26, "ወደቂቁ ፡ ለፍሬ ፡ ዕስሮሙ ፡ ወይምሄል።"),
    (1, 27, '" ወደቂቁ ፡ ለዛሪ.፡ ዘምሪ ፡ ኤታን ፡ ወኤማን ፡ ወከልከል ፡ ወዳራ ፡ ዙኵለ’ሙ ፡ ኃምስቱ።'),
    (1, 28, "ወደቁቁ ፡ ለከር“ ፡ አከር ፡ ዘአጽ ር0 ፡ አስራኤል ፡ ወዐፀለወ ፡ በውግዝ።"),
    (1, 29, '"ወደቂቀ ፡፣ ኤታን ፣ አዛርያ።'),
    (1, 30, '" ወደቁቀ ፡ አሶሮ 10 ን ፣ አለ ፡ ተወልዱ ፡ ሎቱ ፡ እኢያሬሄም ፡ ወአራም ፡ ወክሌብ።'),
    (1, 31, "ወአራም ፡ ወለዶ ፡ ለ አሚናዳብ ፡ ወአሚናዳብ ፡ ወለዶ ፡ ለነአዕን ፡ መልአከሙ፡ ፡ ለቤተ ፡ ይሁዳ።"),
    (1, 32, "'' ወነአሶ ን ፡ ወለዶ ፡ ለሰልሞን ፡ ወሰልሞን ፡ ወለዶ ፡ ለብፆዝ።"),
    (1, 33, "“ወብፆዝ ፡ ወለዶ ፡ ለፆቤድ ፡ ወፆብድ ፡ ወለዶ ፡ ለአክሰይ።"),
