    (1, 40, '"„መአር ፡ወ ለድ ፡ ለኦርኒ ፡ ወኦአርኒ ፡ ወለድ ፡ ለቤስሌሄን።'),
    (1, 41, '" ወኣምድኅረገ! ፡ ቦአ ፡ አሮም ፡ ኀበ ፡ ወ 5 | ለተ ፡ ማኪር ፡ አቡሁ ፡ ለገላኣድ ፡ ወከመገ! ፡ ነሥኣ ፡ ዓመታቲሁ ፡ ስላ ፡ ወወለደት።'),
    (1, 42, ';; "*]. ሎቱ ፡ ለሱትብ።'),
    (1, 43, "= ወሱጉብ ፡ ወለዶ ፡ ለአ. የኤር።"),
    (1, 44, "ወከኮነ ፡ ሎቱ ፡ ዕሥራ. ፡ ወሠለስቱ ብሔር ፡ በገላኣድ።"),
