    (1, 48, "ወክት ፡ ዪቁቁ ፡ ለአ.ያሬሜሃል ፡ በዙሩ ፡ ለአስሮሙ ፡ በዙሩ ፡ አራማ ፡ ወብዓናን ፡ ወኦአሪን ፡ ወአዕሶም ፡ አትሆሙ።"),
    (1, 49, "“ወክከነት ፡ ክልአት ፡ ብአለሊት ፡ ለአ.ያራም ፡ ወስማ ፡።"),
