        1,
        51,
        '"ወክከኑ ፡ ደቂቀ ፡ ራበ ፡ በዙሩ ፡ ib. ኣቤስሄል] A ኢ.ቢሲሄል. — 17. አብጊሪገ] ኋ አቤግያ. ~~ ፣8. አምሳእገ] ኋ ኦኮመሳእ. ~~ 15. አሶሮምን] A ኣአስሮም. ~~ 10. ኦርሃ] ላ ሆርሃ. = 21. ኣአሮምገ ኋ አሥሮም. — b. ወከመዝ] ኋ ውእቱ. ~~ 0. ጓመ ታቲሁ] ኮ አዓማታቲሁ s፤ር; ኋ ወአመታቲሁ. — 50. ሴጕብገ] ኋ ዜጉብ. —- 22. ብሔር] ኋ አኅጉር. ~= 23. ቁና ትገ ኮ ሊቃናተ. — ፤b. ስአህጕሪሃ] ላ ወአዋልዲሃ. — ፤ዕ. ብሔር] ኋ አኅጉር. = 0. ኵሎንኝ ፡ እላኝቱ] A እሉ ፡ ዙሉ. ~= 24. አቦሮመሙ] ላ አሥሮም. ~~ 0b. ካሌብ] ኮ ካልእ. ~~ ሃ0. ኣስዶፎድ] ኋ አስሖር. ~— i. aከte አቡሆሙ ኮ dd. ለ. — ፣b. ጸተቁጫዔንገ] ኋ ለደቂቀ ፣ ሐዊያንኝ. — 23. ኢያሬጫሜሃል] ኋ ኢይሬፊም ሃል. — ፣b. በዙሩ ፡ ስአስሮሙ] ኋ በዙሪረ ፡ አሥሮም. ~~ ፤ዕ. አራማ] A አራም. ~~ ፣». ብዓናኝ] ኋ በኣናንኝ. ~~ የ. አሪንገ] ኋ አራንም. ~~ 26. ካልእት ፡ ብእሲት] ኮ ካልእተ።',
