    (2, 40, '424 " (ይሩ • [ሃቦ • (ያ • በለጻጫሇl \'-° "ሇ/ረሜሇይ! " In « (Ndllle ያlle “ (I .፡ ወግዘንቱ ፡ ልደቱ ፡ ለሰረ.:።'),
