    (4, 15, "ኤል ፡ ወልዬ ፡ አኢ.ያስእ ፡ ወልደ ፡ አክከአዛብ ፡ ወልደ ፡ አብድሄል ፡ ወልደ ፡ አ.ዩኒ ፡ መልአከ ፡ ቤተ ፡ አበዊሆሙ።"),
    (4, 16, "“ወሣደሩ ፣ በገላአደ ፡ ወበበሳን ፡ ወበአሕቁለ.ሆሙ ፡ ወበዙሉ ፡ አዕጻዳቲሆመሙ ፡ ወበዙሉ ፡ አድያሚሆሙ ፡ ለሰሮን ፡ አስከ ፡ ዐአቶመሙ።"),
