    (6, 23, '"ወኮነ ፡ ተል ፡ ልደቶሙ ፡ ለዪቂቀ ፡ በኮር ፡ ወመላአክተ ፡ ቤተ ፡ አበዊሆሙ ፡ እለ ፡ ጽኑዓን ፡ በኀይል ፡ ፪ዜ ፡ ወጀ።'),
