    (
        8,
        22,
        '"ወሰለብዎሙ ፡ ወለሳኦል፤ ፡ መተርያ ፡ ርእሶ ፡ ወተማልአዎ ፡ ምስለ ፡ ንዋዩ ፡ ቅሉ ፡ ወፈነወውዎ ፡ በሓውርቲሆሙ ፡ ከመ ፡ ይዚሁንዉ ፡ ለአነልክቲሆመሙ ፡ ወለሕዘቢ.ሆሙ።',
    ),
    (8, 23, '"ሠ አንበሩ ፡ ንዋየ ፡ ሐቅሉ ፣ ለሳዖኦል ፡ በቤተ ፡ አማልክዢሆሙ ፡ ወርአሶፉ ፣ አንበሩ ፡ ቤተ ፡ 1 ደንጎን ፡ አምላከኮሙ።'),
    (8, 24, '"ወሰምዑ ፡ ኵሎ’ሙ ፡ አለ ፡ ይነብሩ ፡ በሓውርት ፡ ገላአድ ፡ ኵሎ ፡ ዘገብሩ. ፡ ኢ.ሰሉ ፡ ላዕለ ፡ ሳዖል ፡ ወላዕለ ፡ አስራኤል።'),
    (
        8,
        25,
        "“ወተንሥኡ ፡ አምበሓውርተ፡ ገላአድ ፡ ዙሉ ፡ ዕደወ፡ ፡ ጽኑዓን ፡ ወሐፈስዖዎ ፡ በፍና ፡ ለሳኦል ፡ ወአብድንተ ፡ ሠለስ ቱ ፡ ደቂቁ ፡ ወአብጽሕዎሙ ፡ ብሔረ ፡ ቤስ ፡ ወቀበሩ ፡ አዕጽምቲሆሙ ፡ መትሕተ ፡።",
    ),
