    (8, 30, "| ኣ], ወተጋብኡ ፡ ዙሉ ፡ ደቂቀ ፡ አስራኤል ፡ ኀበ ፡ ዳቁት ፡ በብሔረ ፡ ኬብሮን ፡ ወ ፣ ] ይቤልዎ ፡ ነዋኬ ፡ ዐጽምክ ፡ ወሐቋቁከ ፡ ንሳነ።"),
