    (8, 35, "ወቂ !• ብኣዎ ፡ ለዳዊት ፡ ከመ ፡ ይኩን ፡ ንጉሠ ፡ .በ ፡ አስራኤል ፡ በከመ ፡ ቃለ ፡ አግዚኣብሒ ር ፡ ዘከነ ፡ በአደዊሁ ፡ ለሳሙኤል።"),
