    (8, 37, 'አንከ ፡ ዝየ ፡ ወአቅቀደዪመ ፡ አ"ኒዘ ፡ ጸወነ ፡ ጽዮን ፡ ወዛቲ ፡ 6አቲ ፡ ሀገረ ፡ ዳዊት።'),
