        "ኣሉ ፡ አመንቱ ፡ አምዶቁቀ ፡ ጋድ ፡ መላአክተ ፡ ሐሪ ፡ ወአሐቴ. ፡ ኣምኔኦሆ መ ፡ ለምእት ፡ ዓመት ፡ ዘይንአስ ፡ ይመስል ፡ በውርዙት ፡ ወዐበ.ይ ፡ በአልፍ።",
