        "ዝሪ ክ ክብ ዛ ዳናና ማጃ ሠ ወጥ Py ao መ መ ክመ „ኣው 1 ፡ መላአክት ፡ ርኡሳን ፡ ፲፻ ፡ ወምስሌሆመ ፡ ዕደው ፡ ስርሣግቁዋን ፡ በንዋየ ፡ ሐቅል ፡ ወበወላትው ፡ ወበከ። ያንው ፡ ፲፫ ፡ ፮፻።",
