    (19, 5, "ወተመይጠ ፣ አርፍ ፡ ወርአዙ ፡ ለንጉሥ ፡ ዳዊት ፡ 10 ወጸርበዕቱ ፡ ደቂቁ ፡ ኃቡኣን ፡ ወኦርናበ ፡ ሀሎ ፡ ውስተ ፡ ምክያደ ፡ አክል።"),
