        "=ወይቤሉ፡ ፡ ዳዊት ፡ ለፆኦርፍ ፡ ሀበ፤ ፡ አንክ ፣ መካነ ፡ ጕርንከ ፡ ወእሕንጽ ፡ በሂየ ፡ ቤተ ፡ ምሥዋዕ ፡ ለኣግዚ. ኣብሔር ፡ ወሀበኒ ፡ ወአለሣሮጠኒ ፡ ኪያሁ ፡ መካነ ፡ በብዙ ፡ ሣጥ ፡ ወታንትግ ፡ ዛ ፣; ቲ ፡ መቅሠፍት ፡ እምሕገዝብየ።",
