    (
        20,
        7,
        "\"ወይቤ ፡ ዳቁች ፡ ንጉሥ ፡ ሰሎሞን ፡ ወልድየ ፡ ዓዲሁ ፡ ደቂቅ ፡ ውእቱ ፡ ወል. 19 ጸንዐ ፡ ወቤተ ፡ ከመ ፡ ይሣኀንፅ ፡ ለአግዘ.ኣብሇሔሑር ፡ ለዕበሮ ፡ ወለስም ፡ ዕበቢ.ይ ፡ ወለስ ብሐኝ' ፡ በውስተ ፡ ዙሉ ፡ ምድር ፡ አስተዳሉ ፡ ሎቱ።",
    ),
    (20, 8, 'ወአስተዳለወ ፡ ዳዊት ፡ ብዙሣ ፡ ንዋየ ፡ ብርት ፡ ወሣጺን ፡ ወዕፀወ ፡ ዘግበት ፡ ወአብ? ፡ ውቁረ ፡ ዘአልቦ ፡ "ልዬ ፡።'),
    (21, 1, "ዘአንበለ ፡ ይሙት። ወጸወዖፆ ፡ ለሰሎሞን ፡ ወልዳና ፡ ወአወፈዮ ፡ ከመ ፡ ይሣኀንጽ ፡ ቤተ ፡ ለስመ ፡ አግዚኣብሔር ፡ አምላክ ፡ አስራኤል።"),
