    (24, 17, "\"እሉ ፡ ኵለ’መሙ ፡ አሙንቱ ፡ ደቂቀ ፡ ኤማን ፡ ዘየዐነገር ፡ ወያነብብ ፡ በቅድመ ፡ ጎጉሥ ፡ በቃላተ ፡ አግዚኣብሔር ፡ ወይነፍ'ኑ ፡ ቀርነ።"),
