    (
        24,
        19,
        'ኵሰ"ዕ ፡ ሱሉ ፡ ታከለ ፡ ዶበቸሀሙ ፡ ኮቢቤብሐሑ ፣ ወሃብ ፣ ዘጥፌማመ፡ ሠት፡፥ስ፣ [ኣብሔር ፡ በጸናጽል ፡ ወበብዕዛ ፡ ወበአቅርንት ፡ አለ ፡ ቅሩበን ፣ ኀበ ፡ ንገሥ ፣፡ወ አሳፍ ፡ ወአ.ዱቱን ፡ ወኤማን።',
    ),
    (24, 20, '"ወከ! ፡ "ነ„ልቁሙ ፡ ምስለ ፡ አኃዊሆሙ ፡ ምሁራ።'),
    (24, 21, "ን ፡ ወልብዋን ፡ ከመ ፡ ይሰብሑ ፡ ወይዘምሩ ፡ ለአግዚአብሔር ፡ ፪፻ ፡ ወዝዢወቿ።"),
    (24, 22, '"ወወእቆቶሙ ፡ ክዕበ ፡ ተዓፀዉ ፡ በበ ፡ አብሬቶሙ ፡ ንኢሳንሂ ፡ ወዐቢያንሂ ፡ ወአለ ፡ ፍጹማን ፡ ወምሆሁራ.ን።'),
    (24, 23, '" ወወዕአ ፡ ቀዳማይ ፡ ዕፅ ፡ ለአላሳፍ ፡ ወለደቂቁ ፡ ወለአጋዊሁ ለዮሴናፍ።'),
    (24, 24, "ወለጎዶልያስ ፡ ካዕብ ፡ ኤንያ ፡ ወአኃዊሁ ፡ ወደቁቆሙ ፡ ፲ወ፪።"),
    (24, 25, '"ወሣልስ ፡ ዝኩር ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲ወ፪።'),
    (24, 26, '"ራብዕ ፡ ኢያዝሪ ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲፪።'),
    (24, 27, '!" ኃምስ ፡ ምንተንያስ ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲፪።'),
    (24, 28, "ሳድስ ፡ ቡቁያስ ፡ ወፉዶቂቁ ፡ ወእ ኃዊሁ ፡ ፲፪።"),
    (24, 29, "''ሰብፅዕ ፡ አስራኤል ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲፪።"),
    (24, 30, "ሳምን ፡ ኢያሲሂያስ ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲፪።"),
    (24, 31, '"ታስ ፡ ምንታንያስ ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲፪።'),
    (25, 1, "ዓሥር ፡ ኤሚ ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲፪። “ወዐፀሠርቱ፡ ፡ ወአሐዱ ፡ አዝሪቱል ፡ ወደቂቁ ፣ ወስ ኃዊሁ ፣ ፲፪።"),
