    (25, 3, "ወአኃዊሁ ፡ ፲፪። “ዐሠርቱ ፡ ወስድስቱ ፡ አናንያስ ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲6።"),
    (25, 4, '" ዐሠ ርቱ ፡ ወሰብዕዐቱ ፡ ኢ.ዬዩስጠያሇን ፡ ወዪቁቁ ፡ ወአኃዊሁ ፡ ፲፪። "ዐሠርቱ ፡ ወሰማንቱ፡ ፡ አናኒ ፡ ወዪቁቁ ፡ ወአኃዊሁ ፡ ፲፪።'),
    (25, 5, '"ዐሠርቱ ፡ ወተስዕቱ ፡ “ሜሌቲ ፡ ወደቂቁ ፡ ወክ »ኃጥሆ ፡ ፲፪። “ዕሥ’ራ. ፡ ኤልያቲ ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲፪።'),
    (25, 6, '“ዕሥራ. ፡ ወአሐዱ ፡ ኢአ. ያቱር ፡ ወደቂቁ ፡ ወአኃዊሁ ፡ ፲፪። " ዕሥሪ ፡ ወክልኤቱ ፡ ገዶለሊ.ቲ ፡ ሀዴቁቁ ፡ ወአ: ዊሁ ፡ ፲፪።'),
    (25, 7, "\"ዕሥ'ሪ ፡ ወሠለስቱ ፣ መአዚ.ዮት ፡ ሠደቁቁ ፡፣ ወአኃዊሁ ፡ ፲፪። \" ዕሥራ. ፡ ወአርበዕቱ ፡ ሰሬሜን'ያዜር ፡ ወዪዴቁቁ ፡ ወአጋዊሆሁ ፡ ፲፪።"),
    (25, 8, 'NNN I. "ወለክዛ:ለተ ፡ ዐቂበ ፡ አንቱኾጽ ፡ ደቁቱ ፡ ቁሬ ፡ መሳለም ፡ ወእምደቁ " ቁ ፡ ቁሬ ፡ ወአምዬቁቂቁ ፡ አሳፍ።'),
