    (25, 12, "ሳድስ ፡ ስካር ፡ ሳብዕ ፡ ቲላኘ ፡ ሳምን ፡ አስመ ፡ በረከ ፡ አሣግሀ.ኣብሐሒር ፡ አምላ ከ።"),
