    (
        27,
        4,
        "\"ወላዕለ ፡ መዘግብ ተ ፡ ቤተ ፡ ንጉሥ ፡ ወጎዝገሙት ፡ ወልዳ. ፡ ለአ.ዮሄል = ወላዕለ ፡ መዛግብት ፡ አለ ፡ ሀለዉ. ፡ በውስተ ፡ ሐቅል ፡ ወውስተ ፡ አዕጻጻት ፡ ወውስተ ፡ አብያት ፡ ኣለ ፡ ይከውኑ ፡ ') ለንጉሥ’ ፡ በብሒረ ፡ ሐቅል ፡ ወላዕለ ፡ ማሣፈሩ ፡ ዮናታን ፡ ወልዱ ፡ ለኡዲሄል። “አስመ ፡ ለአለ ፡ የሐርስቁ ፡ ለምድር ፡ ወለአለ ፡ ዕትቀነይዊ ፡ ተሠይመ ፡ አዝራል. ወልደ ፡ ኬሉብ።",
    ),
    (27, 5, '"ወላዕለ ፡ ገራውህ ፡ ሂኢ ፡ ለብሔረ ፡ ራማቲያ። ወላዕለ ፡ መዛግ ብት ፡ አለ ፡ ሀለዉ ፡ በውስተ ፡ አዕጻዳተ ፡ ወይን ፡ ዘብዲ ፡ ወልዶ ፡ ሳፍኒ።'),
